// Run only through the guarded qualification harness in a fresh synthetic profile.
import React from 'react';
import {createRoot} from 'react-dom/client';
import App from '../../src/App.jsx';
import '../../src/index.css';
import '../../src/studio.css';
import {createProjectStore} from '../../src/persistence/projectStore.js';
import {restoreWorkspace} from '../../src/persistence/workspaceRestore.js';
import {createGraphState} from '../../src/graph/graphState.js';
import {PROJECT_DATABASE} from '../../src/persistence/projectSchema.js';
const query=new URLSearchParams(location.search),token=query.get('token'),cases=[];
const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms??40));
const panel=()=>document.querySelector('[data-resume-state]'),workspace=()=>document.querySelector('[data-workspace-storage]');
const button=(text,scope=document)=>[...scope.querySelectorAll('button')].find(b=>b.textContent===text);
const check=(value,label)=>{if(!value)throw Error(label);};
async function wait(fn,label){const end=Date.now()+25000;while(Date.now()<end){if(await fn())return;await pause();}throw Error('Timeout '+label);}
function edit(element,value){Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(element,value);element.dispatchEvent(new Event('input',{bubbles:true}));}
let store,root,peer;
async function peerWrite(projectId,text){const s=createProjectStore();try{const before=await restoreWorkspace(s,projectId),p=await s.readProject(projectId);const sources=before.sources.map(source=>({key:source.provenance.sourceKey,name:source.provenance.name,kind:source.provenance.kind,mediaType:source.provenance.mediaType,originalId:source.provenance.originalId,bytes:source.provenance.kind==='parser'?source.bytes:new TextEncoder().encode('h0: '+text).buffer}));const receipt=await s.saveWorkspace(projectId,p.revision,{sources,graph:createGraphState([{id:'peer-h0',vertices:text.split(', ')}]),graphSourceKeys:before.root.graph.provenance.sources.map(ref=>before.sources.find(source=>source.objectId===ref.objectId).provenance.sourceKey),metadata:before.metadata,mapping:before.mapping,parser:before.root.graph.provenance.parser});const verified=await restoreWorkspace(s,projectId);return{revision:receipt.revision,rootSha256:verified.root.sha256,graphFingerprint:verified.graph.graphFingerprint};}finally{await s.close();}}
async function ready(){await wait(()=>workspace()&&workspace().dataset.workspaceStorage!=='loading'&&panel().dataset.resumeState!=='RESTORING','usable App');await pause(180);}
async function report(ok,extra={}){document.getElementById('result').textContent=JSON.stringify({ok,cases,...extra});await fetch('/__scope7e_report?token='+token,{method:'POST',body:JSON.stringify({ok,phase:'first',cases,...extra})});}
try{
 check((await(await fetch('/__scope7e_guard?token='+token)).json()).isolated,'isolated guard');
 if(query.get('phase')==='peer'){
  window.scope7eCorrectivePeer={write:peerWrite,otherProject:async projectA=>{const s=createProjectStore();try{const original=await restoreWorkspace(s,projectA),p=await s.createProject();await s.saveWorkspace(p.projectId,p.revision,{sources:original.sources.map(source=>({key:source.provenance.sourceKey,name:source.provenance.name,kind:source.provenance.kind,mediaType:source.provenance.mediaType,originalId:source.provenance.originalId,bytes:source.bytes})),graph:original.graph,graphSourceKeys:original.root.graph.provenance.sources.map(ref=>original.sources.find(source=>source.objectId===ref.objectId).provenance.sourceKey),metadata:original.metadata,mapping:original.mapping});return{projectId:p.projectId,sha256:(await restoreWorkspace(s,p.projectId)).root.sha256};}finally{await s.close();}}};
 }else{
  check(!(await indexedDB.databases()).some(d=>d.name===PROJECT_DATABASE),'fresh synthetic storage');store=createProjectStore();root=createRoot(document.getElementById('root'));root.render(React.createElement(React.StrictMode,null,React.createElement(App)));await ready();
  const transfer=new DataTransfer();transfer.items.add(new File(['h0: A, B\nh1: B, C'],'alpha.txt',{type:'text/plain'}));const input=document.querySelector('input[type=file]');input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));await wait(()=>workspace().dataset.workspaceStorage==='committed','source committed');[...document.querySelectorAll('.hg-input-card button')].find(b=>/convert/i.test(b.textContent)).click();await wait(()=>workspace().dataset.workspaceStorage==='committed'&&panel().querySelectorAll('dd')[1].textContent.includes('Available'),'graph committed');await pause(600);
  const id=(await store.defaultProject()).projectId,known=(await store.readProject(id)).revision,original=(await restoreWorkspace(store,id)).root.sha256,oldText=document.querySelector('.hg-input-card textarea').value;cases.push({case:'native-original-UI-source-graph-and-owner-acknowledged',revision:known,rootSha256:original});
  peer=window.open(`${location.pathname}?phase=peer&token=${token}`,'scope7e-corrective-owned-peer');await wait(()=>peer?.scope7eCorrectivePeer,'second context');const b=await peer.scope7eCorrectivePeer.otherProject(id);cases.push({case:'separate-project-B-native-root-created',projectId:b.projectId,rootSha256:b.sha256});
  const foreign=await peer.scope7eCorrectivePeer.write(id,'FOREIGN, NEW');check((await restoreWorkspace(store,id)).root.sha256===foreign.rootSha256,'new foreign root valid');cases.push({case:'native-peer-newer-revision-with-no-optional-notification',...foreign});
  check(document.querySelector('.hg-input-card textarea').value===oldText&&panel().dataset.resumeState!=='STALE','old UI still unreviewed');cases.push({case:'old-owner-has-not-adopted-foreign-source-or-state'});
  panel().querySelector('details').open=true;button('Delete saved workspace…',panel()).click();await wait(()=>document.querySelector('dialog[open]'),'normal explicit confirmation');check(document.activeElement.textContent==='Cancel','safe initial focus');cases.push({case:'normal-delete-confirmation-opens-from-known-owner'});button('Confirm',document.querySelector('dialog')).click();await wait(()=>document.querySelector('[role=alert]')?.textContent.includes('Nothing was cleared'),'conflict rejection');
  const retained=await restoreWorkspace(store,id);check(retained.root.sha256===foreign.rootSha256&&retained.graph.graphFingerprint===foreign.graphFingerprint,'new durable root/source/graph preserved');check((await restoreWorkspace(store,b.projectId)).root.sha256===b.sha256,'B preserved on A conflict');cases.push({case:'former-S7E-EXACT-SHA-001-reproduction-PASS',reviewedRevision:known,foreignRevision:foreign.revision,newerRootRetained:true,foreignWorkspaceDeleted:false,projectBUnchanged:true});
  check(panel().dataset.resumeState==='STALE'&&!/^Saved$|^Ready\. No workspace changes to save\.$/.test(document.querySelector('[data-durability]').textContent),'truthful stale UI');check(button('Delete saved workspace…',panel()).disabled,'fresh review required');cases.push({case:'bounded-conflict-no-success-no-auto-retry-requires-review'});
  button('Reload saved data',panel()).click();await wait(()=>panel().dataset.resumeState!=='STALE'&&panel().dataset.resumeState!=='RESTORING','explicit reload');if(!workspace()){button('Resume workspace',panel()).click();}await ready();check(document.querySelector('.hg-input-card textarea').value.includes('FOREIGN'),'new source explicitly reviewed');cases.push({case:'explicit-reload-review-establishes-new-owner-lineage'});
  edit(document.querySelector('.hg-input-card textarea'),'h0: OWNED, UPDATE');await wait(async()=>workspace().dataset.workspaceStorage==='committed'&&(await restoreWorkspace(store,id)).root.sha256!==foreign.rootSha256,'acknowledged same-owner progression');[...document.querySelectorAll('.hg-input-card button')].find(b=>/convert/i.test(b.textContent)).click();await wait(()=>workspace().dataset.workspaceStorage==='committed'&&panel().querySelectorAll('dd')[1].textContent.includes('Available'),'owner graph progression');await pause(350);cases.push({case:'acknowledged-same-owner-source-graph-chat-progress-does-not-falsely-conflict'});
  panel().querySelector('details').open=true;button('Delete saved workspace…',panel()).click();await wait(()=>document.querySelector('dialog[open]'),'current-owner confirmation');button('Confirm',document.querySelector('dialog')).click();await wait(async()=>!(await store.readWorkspace(id)).root,'normal current-owner delete');check((await restoreWorkspace(store,b.projectId)).root.sha256===b.sha256,'B preserved after A deletion');cases.push({case:'current-owner-delete-PASS-and-project-B-remains-intact'});
  peer.close();root.unmount();await store.close();await report(true,{nativeIndexedDB:true,notificationFault:'Independent native product-store writer intentionally sends no optional notification; storage transactions are not mocked',formerBlockerClosed:true});
 }
}catch(error){peer?.close();root?.unmount();await store?.close();await report(false,{error:String(error),stack:error.stack});}
